insert into public.app_config (key, value, description) values
  ('ranking_weights', '{"ramp_swipes":50,"components":{"stated":{"w0":0.4,"w50":0.2},"affinity":{"w0":0.05,"w50":0.15},"visual":{"w0":0.05,"w50":0.15},"deal":{"w0":0.15,"w50":0.15},"distance":{"w0":0.1,"w50":0.1},"freshness":{"w0":0.08,"w50":0.08},"quality":{"w0":0.07,"w50":0.07},"headroom":{"w0":0.05,"w50":0.05},"matchability":{"w0":0.05,"w50":0.05}}}'::jsonb, 'Soft-score weights; each slides from w0 at swipe 0 to w50 at swipe 50+.'),
  ('exploration', '{"batch_size":20,"rate_start":0.15,"rate_after":0.08,"after_swipes":300}'::jsonb, 'Share of each batch that tests uncertain tastes.'),
  ('limits', '{"likes_per_day":150,"superlikes_per_day":3,"messages_per_minute":20,"dealer_reply_hours":48,"offplatform_reply_days":14,"private_reply_hours":72,"questions_every_swipes":20}'::jsonb, 'Daily like/super-like caps, message rate, dealer reply windows, question pacing.'),
  ('learning', '{"affinity_cap":30,"pass_weight":0.5,"superlike_weight":2,"taste_pass_share":0.3}'::jsonb, 'How swipes update taste: tally cap, pass and super-like weights.'),
  ('tax_tn', '{"state_rate":0.07,"local_rate":0.0225,"local_cap":1600,"single_article_rate":0.0275,"single_article_min":1600,"single_article_max":3200,"title_registration":120,"doc_fee_taxable":true}'::jsonb, 'Tennessee tax and fee estimates for out-the-door math. [VERIFY TN rates]'),
  ('finance', '{"default_term_months":72,"default_credit_tier":"good","default_doc_fee":699,"apr":{"new":{"excellent":5.9,"good":7.4,"fair":10.9,"rebuilding":15.9},"used":{"excellent":7.4,"good":9.9,"fair":14.4,"rebuilding":19.9}}}'::jsonb, 'Payment estimator assumptions: APR by credit tier, default term and doc fee.'),
  ('cost_to_own', '{"miles_per_month":1100,"gas_price_per_gallon":3.05,"electricity_per_kwh":0.13,"ev_miles_per_kwh":3.4,"insurance_base_monthly":95,"insurance_per_10k_value":14,"maintenance_base_monthly":45,"maintenance_per_year_of_age":6}'::jsonb, 'Monthly cost-to-own estimate inputs.'),
  ('ai', '{"daily_budget_usd_per_user":0.25}'::jsonb, 'Per-user daily AI budget; beyond it the app falls back to templates.'),
  ('deck', '{"empty_threshold":6,"candidates":300,"explore_candidates":100}'::jsonb, 'Deck sizes and the empty-deck rescue threshold.'),
  ('purchase_prompts', '{"days_after_match":[14,30]}'::jsonb, 'Days after a match to ask "Did you buy it?".'),
  ('launch_market', '{"id":"nashville","zip":"37203"}'::jsonb, 'Launch market and its center ZIP.'),
  ('billing', '{"matched_lead_price_usd":40,"promotion_price_usd":49,"promotion_days":7,"insights_monthly_usd":199}'::jsonb, 'Displayed prices for matched leads, promotions and insights. [SET] Keep in sync with the Stripe prices.'),
  ('promotions', '{"max_share":0.1,"boost":0.06}'::jsonb, 'Promoted listings: max share of a deck batch and the ranking boost.'),
  ('private_sales', '{"max_listings_per_year":4,"min_photos":3,"max_photos":20,"listing_days":60}'::jsonb, 'Private sellers: yearly listing cap [VERIFY TN dealer-license threshold], photo limits, listing length.'),
  ('moderation', '{"review_score":0.35,"block_score":0.7,"price_too_low_ratio":0.65,"phash_max_distance":6}'::jsonb, 'Listing risk thresholds: review and block scores, too-good price ratio, photo match distance.'),
  ('insights', '{"k_anonymity":5}'::jsonb, 'Demand insights: minimum distinct buyers per reported number (k-anonymity).');
